// ===== ВАЛИДАЦИЯ, ЛИМИТЫ, ИДЕМПОТЕНТНОСТЬ, ВЫКЛЮЧАТЕЛЬ =====
const MAX_INPUT_CHARS = 2000;
const MAX_ORDERS_PER_HOUR = 20;
const PRICE_RUB_PER_1K_TOKENS = 0.60;
const EST_OUTPUT_TOKENS = 400;
const SYSTEM_PROMPT_TOKENS = 300;

function hash32(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

const t0 = Date.now();
const settingsRow = $('NocoDB: настройки').first().json ?? {};
const rawFlag = settingsRow.value;
const processing_enabled = rawFlag === undefined ? true : !['false', '0', 'off', 'no'].includes(String(rawFlag).toLowerCase());

const out = [];
for (const item of $('Приём заказа').all()) {
  const body = item.json.body ?? {};
  const headers = item.json.headers ?? {};
  const errors = [];

  if (body.text !== undefined && typeof body.text !== 'string') errors.push('text_must_be_string');
  if (body.qty !== undefined && typeof body.qty !== 'number') errors.push('qty_must_be_number');

  const customer = String(body.customer ?? '').trim();
  const contact = String(body.contact ?? '').trim().toLowerCase();
  const text = String(body.text ?? '').replace(/\r\n/g, '\n').trim();
  const client_order_id = body.order_id ? String(body.order_id).trim() : null;

  if (!customer) errors.push('customer_required');
  if (!contact) errors.push('contact_required');
  if (!text) errors.push('text_required');
  if (text.length > MAX_INPUT_CHARS) errors.push('input_too_large');

  const depth = Number(headers['x-loop-depth'] ?? 0);
  if (depth > 0) errors.push('loop_detected');

  const headerKey = headers['idempotency-key'] ?? headers['Idempotency-Key'];
  const derived = hash32(contact + '|' + text.toLowerCase().replace(/\s+/g, ' '));
  const idempotency_key = String(headerKey ?? '').trim() || derived;
  const key_source = headerKey ? 'client' : 'derived';

  const received_at = new Date().toISOString();
  const order_id = client_order_id || 'ORD-' + received_at.slice(0, 10).replace(/-/g, '') + '-' + hash32(idempotency_key).toUpperCase();

  const est_input_tokens = Math.ceil(text.length / 3) + SYSTEM_PROMPT_TOKENS;
  const est_total_tokens = est_input_tokens + EST_OUTPUT_TOKENS;
  const est_cost_rub = Number((est_total_tokens / 1000 * PRICE_RUB_PER_1K_TOKENS).toFixed(4));

  if (!processing_enabled) errors.push('processing_disabled');

  const can_process = errors.length === 0;
  const http_code = errors.includes('processing_disabled') ? 503 : errors.includes('input_too_large') ? 413 : errors.includes('loop_detected') ? 508 : 422;

  const agent_input = ['<<<ЗАКАЗ_НАЧАЛО>>>', 'Клиент: ' + customer, 'Текст заказа:', text, '<<<ЗАКАЗ_КОНЕЦ>>>'].join('\n');

  out.push({ json: {
    order_id, idempotency_key, key_source, received_at, agent_input,
    customer, customer_contact: contact, text, text_length: text.length,
    can_process, errors, http_code, est_total_tokens, est_cost_rub,
    max_orders_per_hour: MAX_ORDERS_PER_HOUR, price_per_1k: PRICE_RUB_PER_1K_TOKENS, t0,
    stages: [{ stage: 'validate', status: can_process ? 'ok' : 'rejected', ms: Date.now() - t0 }],
    api_response: { status: 'rejected', order_id, errors },
  } });
}
return out;

// ===== ЖУРНАЛ, ТОЧКА A: ВАЛИДАЦИЯ (пишется ДО ветвления) =====
// http_code: код ответа клиенту, если исход финализирован здесь; null — обработка продолжается
const v = $input.first().json;
const rejected = !v.can_process;
return [{ json: {
  ts: new Date().toISOString(),
  run_id: String($execution.id),
  order_id: v.order_id || 'UNKNOWN',
  stage: 'validate',
  status: rejected ? 'rejected' : 'ok',
  duration_ms: (v.stages && v.stages[0] && v.stages[0].ms) ?? null,
  tokens: null,
  cost_rub: null,
  error: rejected ? (v.errors || []).join('|') : '',
  http_code: rejected ? (v.http_code ?? null) : null,
} }];

const t = $('Валидация и лимиты').first().json;
const rows = $input.all().map((i) => i.json).filter((r) => r && (r.Id || r.id || r.order_id));
const dup = rows.find((r) => String(r.idempotency_key) === String(t.idempotency_key));
const hourAgo = Date.now() - 3600 * 1000;
const recent = rows.filter((r) => { const ts = Date.parse(r.received_at); return Number.isFinite(ts) && ts > hourAgo; });
const rate_exceeded = recent.length >= t.max_orders_per_hour;
const is_duplicate = Boolean(dup);
return [{ json: {
  ...t, is_duplicate, rate_exceeded, orders_last_hour: recent.length,
  previous_order_id: dup ? (dup.order_id ?? null) : null, previous_status: dup ? (dup.status ?? null) : null, previous_result: dup ? (dup.result_json ?? null) : null,
  can_call_model: !is_duplicate && !rate_exceeded, http_code: 200,
  api_response: { status: is_duplicate ? 'duplicate' : 'rate_limited', order_id: t.order_id, previous_order_id: dup ? (dup.order_id ?? null) : null, previous_status: dup ? (dup.status ?? null) : null, orders_last_hour: recent.length },
  stages: [...t.stages, { stage: 'dedup', status: is_duplicate ? 'duplicate' : (rate_exceeded ? 'rate_limited' : 'ok'), ms: Date.now() - t.t0 }],
} }];

// ===== ЖУРНАЛ, ТОЧКА B: ДЕДУП (пишется ДО ветвления на модель) =====
const d = $input.first().json;
const last = (d.stages && d.stages.length) ? d.stages[d.stages.length - 1] : null;
const code = d.is_duplicate ? 'duplicate' : (d.rate_exceeded ? 'rate_limited' : '');
return [{ json: {
  ts: new Date().toISOString(),
  run_id: String($execution.id),
  order_id: d.order_id || 'UNKNOWN',
  stage: 'dedup',
  status: code || 'ok',
  duration_ms: last ? (last.ms ?? null) : null,
  tokens: null,
  cost_rub: null,
  error: code,
  http_code: code ? 200 : null,
} }];

const PRICE_LIST = {
  'FLT-100': { name: 'Фильтр масляный', price: 890 },
  'FLT-200': { name: 'Фильтр воздушный', price: 640 },
  'OIL-5W40': { name: 'Масло моторное 5W-40, 4 л', price: 3200 },
  'BRK-310': { name: 'Колодки тормозные передние', price: 4150 },
};
const URGENCY = ['normal', 'urgent'];
const URGENT_SURCHARGE = 0.15;

const t = $('Валидация и лимиты').first().json;
const db_record_id = $('NocoDB: создать заказ').first().json.Id || $('NocoDB: создать заказ').first().json.id;

const res = $input.first().json ?? {};

let llm_ok = true;
let error_code = null;
let error_message = '';
let parsed = null;
let raw = res.output ?? res;

if (raw && typeof raw === 'object' && !Array.isArray(raw) && !('items' in raw)) {
  const e = raw.error ?? raw.message ?? null;
  if (e) {
    llm_ok = false;
    error_message = String(typeof e === 'object' ? JSON.stringify(e) : e).slice(0, 500);
    error_code = /timeout|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(error_message) ? 'llm_timeout' : /401|403|Api-Key|unauthor/i.test(error_message) ? 'llm_auth_error' : /429|rate|quota/i.test(error_message) ? 'llm_rate_limited' : 'llm_unavailable';
    raw = null;
  }
}

if (llm_ok) {
  if (typeof raw === 'string') {
    const clean = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
    try { parsed = JSON.parse(clean); } catch (e) { llm_ok = false; error_code = 'llm_bad_format'; error_message = 'invalid json'; }
  } else if (raw && typeof raw === 'object') {
    parsed = raw;
  } else {
    llm_ok = false; error_code = 'llm_bad_format'; error_message = 'empty output';
  }
  if (llm_ok && !Array.isArray(parsed?.items)) {
    llm_ok = false; error_code = 'llm_bad_format'; error_message = 'items is not an array';
  }
}

const p = parsed ?? {};
const items = [];
const unknown_items = [];
for (const it of (Array.isArray(p.items) ? p.items : []).slice(0, 50)) {
  const sku = it && it.sku ? String(it.sku).trim().toUpperCase() : null;
  const name = String(it?.name ?? '').trim().slice(0, 120);
  let qty = Number(it?.qty);
  if (!Number.isFinite(qty) || qty < 1) qty = 1;
  qty = Math.min(Math.floor(qty), 999);
  const known = sku && PRICE_LIST[sku];
  if (known) { items.push({ sku, name: known.name, qty, price: known.price, sum: known.price * qty }); } else { unknown_items.push({ sku, name, qty }); }
}

const urgency = URGENCY.includes(p.urgency) ? p.urgency : 'normal';
const delivery_address = String(p.delivery_address ?? '').trim().slice(0, 300);
const subtotal = items.reduce((s, i) => s + i.sum, 0);
const surcharge = urgency === 'urgent' ? Math.round(subtotal * URGENT_SURCHARGE) : 0;
const total_rub = subtotal + surcharge;
const needs_review = !llm_ok || unknown_items.length > 0 || items.length === 0 || !delivery_address;
const status = !llm_ok ? 'failed' : (needs_review ? 'needs_review' : 'done');

const review_reasons = [];
if (!llm_ok) review_reasons.push('llm_failed:' + (error_code || 'unknown'));
if (unknown_items.length > 0) review_reasons.push('unknown_items:' + unknown_items.length);
if (items.length === 0) review_reasons.push('no_known_items');
if (!delivery_address) review_reasons.push('no_address');
const review_reason = review_reasons.join('|');

const tokens = llm_ok ? Math.ceil((t.text.length + JSON.stringify(parsed).length) / 3) + 300 : 0;
const cost_rub = tokens ? Number((tokens / 1000 * t.price_per_1k).toFixed(4)) : 0;

const retry_payload = llm_ok ? '' : JSON.stringify({ customer: t.customer, contact: t.customer_contact, text: t.text, order_id: t.order_id, idempotency_key: t.idempotency_key });

const alert_text = llm_ok ? '' : ['🔴 <b>Заказ не обработан</b>', '<code>' + t.order_id + '</code>', '', '<b>Этап:</b> разбор заказа моделью', '<b>Код:</b> ' + error_code, '<b>Детали:</b> ' + error_message.slice(0, 200), '', 'Входные данные сохранены. Перезапуск тем же ключом идемпотентности безопасен.'].join('\n');

return [{ json: {
  ...t, agent_input: undefined, llm_ok, error_code, error_message, retry_payload, alert_text,
  Id: db_record_id,
  http_code: llm_ok ? 200 : 502,
  api_response: llm_ok ? { status: status, order_id: t.order_id, total_rub, needs_review, cost_rub } : { status: 'failed', order_id: t.order_id, error_code, retry_safe: true },
  items, unknown_items, delivery_address, urgency, subtotal, surcharge, total_rub, items_json: JSON.stringify(items), unknown_json: unknown_items.length ? JSON.stringify(unknown_items) : '', needs_review, status, tokens_used: tokens, cost_rub, model_version: res?.result?.modelVersion ?? null,
  review_reason,
  stages: [...t.stages, { stage: 'llm', status: llm_ok ? 'ok' : 'failed', ms: Date.now() - t.t0, tokens, cost_rub, error: error_code }, { stage: 'parse', status: llm_ok ? (needs_review ? 'needs_review' : 'ok') : 'skipped', ms: Date.now() - t.t0 }],
} }];

// ===== ЖУРНАЛ, ТОЧКА C: LLM + РАЗБОР (пишется ДО PATCH) =====
const c = $input.first().json;
const llmStage = (c.stages || []).find((s) => s.stage === 'llm') || {};
const parseStage = (c.stages || []).find((s) => s.stage === 'parse') || {};
const code = c.llm_ok ? 200 : 502;
const ts = new Date().toISOString();
const run_id = String($execution.id);
return [
  { json: { ts, run_id, order_id: c.order_id || 'UNKNOWN', stage: 'llm', status: llmStage.status || (c.llm_ok ? 'ok' : 'failed'), duration_ms: llmStage.ms ?? null, tokens: c.tokens_used ?? null, cost_rub: c.cost_rub ?? null, error: c.error_code || '', http_code: code } },
  { json: { ts, run_id, order_id: c.order_id || 'UNKNOWN', stage: 'parse', status: parseStage.status || 'skipped', duration_ms: parseStage.ms ?? null, tokens: c.tokens_used ?? null, cost_rub: c.cost_rub ?? null, error: '', http_code: code } }
];

// ===== СБОРКА ОТВЕТА КЛИЕНТУ: единая точка для всех веток =====
let out = null;
try {
  const c = $('Проверка ответа и расчёт').first().json;
  out = { api_response: c.api_response, http_code: c.http_code };
} catch (e) {}
if (!out) {
  try {
    const d = $('Проверка дубля и лимита').first().json;
    out = { api_response: d.api_response, http_code: d.http_code };
  } catch (e) {}
}
if (!out) {
  const v = $('Валидация и лимиты').first().json;
  out = { api_response: v.api_response, http_code: v.http_code };
}
return [{ json: out }];

