={{
  (() => {
    const data = $('Проверка ответа и расчёт').first().json;
    if (!data.Id) throw new Error('No Id — запусти сквозным прогоном через вебхук');
    return [
      {
        Id:               Number(data.Id),
        status:           String(data.status || data.api_response?.status || 'needs_review'),
        items_json:       String(data.items_json || '[]'),
        unknown_json:     String(data.unknown_json || '[]'),
        delivery_address: String(data.delivery_address || ''),
        total_rub:        Number(data.total_rub) || 0,
        tokens_used:      Number(data.tokens_used) || 0,
        cost_rub:         Number(data.cost_rub) || 0,
        error_code:       String(data.error_code || ''),
        error_message:    String(data.error_message || ''),
        review_reason:    String(data.review_reason || '')
      }
    ];
  })()
}}
